import heapq

def match(orders):
    trades = []
    buy_book = []  # heap of (-price, seq, id)
    sell_book = []  # heap of (price, seq, id)
    order_info = {}  # id -> [side, price, qty_remaining, seq, status]
    seq_counter = [0]

    def add_to_book(side, oid):
        info = order_info[oid]
        if side == 'buy':
            heapq.heappush(buy_book, (-info[1], info[3], oid))
        else:
            heapq.heappush(sell_book, (info[1], info[3], oid))

    def get_top_valid(book):
        while book:
            item = book[0]
            oid = item[2]
            if oid not in order_info:
                heapq.heappop(book)
                continue
            info = order_info[oid]
            if info[4] != 'active' or info[2] <= 0:
                heapq.heappop(book)
                continue
            return oid
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in order_info:
                info = order_info[oid]
                if info[4] == 'active':
                    info[4] = 'cancelled'
            continue

        oid = order[1]
        side = order[2]

        if typ == 'limit':
            price = order[3]
            qty = order[4]
        elif typ == 'ioc':
            price = order[3]
            qty = order[4]
        elif typ == 'market':
            price = None
            qty = order[3]

        seq_counter[0] += 1
        seq = seq_counter[0]
        order_info[oid] = [side, price, qty, seq, 'active']

        remaining = qty

        if side == 'buy':
            opp_book = sell_book
        else:
            opp_book = buy_book

        while remaining > 0:
            top_oid = get_top_valid(opp_book)
            if top_oid is None:
                break
            top_info = order_info[top_oid]
            top_price = top_info[1]

            if typ == 'market':
                can_match = True
            else:
                if side == 'buy':
                    can_match = top_price <= price
                else:
                    can_match = top_price >= price

            if not can_match:
                break

            trade_qty = min(remaining, top_info[2])
            trade_price = top_price

            if side == 'buy':
                trades.append([oid, top_oid, trade_price, trade_qty])
            else:
                trades.append([top_oid, oid, trade_price, trade_qty])

            remaining -= trade_qty
            top_info[2] -= trade_qty

            if top_info[2] <= 0:
                top_info[4] = 'filled'
                heapq.heappop(opp_book)

        order_info[oid][2] = remaining

        if typ == 'limit':
            if remaining > 0:
                add_to_book(side, oid)
            else:
                order_info[oid][4] = 'filled'
        else:
            order_info[oid][4] = 'filled' if remaining == 0 else 'discarded'

    return trades

